import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.KeyStore;
import java.security.MessageDigest;
import java.security.PrivateKey;
import java.security.Signature;
import java.security.cert.X509Certificate;
import java.security.interfaces.RSAPublicKey;
import java.util.HashSet;
import java.util.HexFormat;
import java.util.Properties;

// Independent JDK verification of keys generated by the Dart initialization tool.
class VerifyKeystore {
    public static void main(String[] args) throws Exception {
        var publicKeys = new HashSet<String>();
        for (int i = 1; i < args.length; i++) {
            var environment = args[i];
            var directory = Path.of(args[0], "android", "keystores", environment);
            var properties = new Properties();
            try (var input = Files.newInputStream(directory.resolve("key.properties"))) {
                properties.load(input);
            }
            var password = properties.getProperty("storePassword").toCharArray();
            var alias = properties.getProperty("keyAlias");
            var keystore = KeyStore.getInstance("PKCS12");
            // Resolve exactly as Gradle's app/file(storeFile) does.
            var keyPath = Path.of(args[0], "android", "app")
                .resolve(properties.getProperty("storeFile")).normalize();
            try (var input = Files.newInputStream(keyPath)) {
                keystore.load(input, password);
            }
            if (!keystore.isKeyEntry(alias)) throw new AssertionError("No private key entry");
            var privateKey = (PrivateKey) keystore.getKey(alias,
                properties.getProperty("keyPassword").toCharArray());
            var certificate = (X509Certificate) keystore.getCertificate(alias);
            certificate.checkValidity();
            var publicKey = (RSAPublicKey) certificate.getPublicKey();
            if (publicKey.getModulus().bitLength() != 4096) throw new AssertionError("Wrong RSA size");
            publicKeys.add(HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256")
                .digest(publicKey.getEncoded())));
            var payload = "Android signing initialization test".getBytes(StandardCharsets.UTF_8);
            var signature = Signature.getInstance("SHA256withRSA");
            signature.initSign(privateKey);
            signature.update(payload);
            var signed = signature.sign();
            signature.initVerify(publicKey);
            signature.update(payload);
            if (!signature.verify(signed)) throw new AssertionError("Signature verification failed");
            signature.initVerify(publicKey);
            signature.update("tampered content".getBytes(StandardCharsets.UTF_8));
            if (signature.verify(signed)) throw new AssertionError("Tampered content accepted");
        }
        if (publicKeys.size() != args.length - 1) throw new AssertionError("Environments share a key");
        System.out.println("verified=" + publicKeys.size());
    }
}
